"use strict";(self.webpackChunkjigsawflux_blog=self.webpackChunkjigsawflux_blog||[]).push([[130],{7735:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"welcome","metadata":{"permalink":"/blog/welcome","editUrl":"https://github.com/JigsawFlux/blog/tree/main/blog/2026-05-15-welcome.md","source":"@site/blog/2026-05-15-welcome.md","title":"Welcome to the JigsawFlux Blog","description":"Welcome to the JigsawFlux Blog \u2014 a space for updates, ideas, and stories from the JigsawFlux open-source community.","date":"2026-05-15T00:00:00.000Z","tags":[{"inline":true,"label":"open-source","permalink":"/blog/tags/open-source"},{"inline":true,"label":"health-tech","permalink":"/blog/tags/health-tech"},{"inline":true,"label":"humanitarian","permalink":"/blog/tags/humanitarian"}],"readingTime":0.875,"hasTruncateMarker":true,"authors":[{"name":"Suresh Thomas","title":"Founder, JigsawFlux","url":"https://github.com/st185229","imageURL":"https://github.com/st185229.png","key":"suresh","page":null}],"frontMatter":{"slug":"welcome","title":"Welcome to the JigsawFlux Blog","date":"2026-05-15T00:00:00.000Z","authors":["suresh"],"tags":["open-source","health-tech","humanitarian"]},"unlisted":false},"content":"Welcome to the JigsawFlux Blog \u2014 a space for updates, ideas, and stories from the JigsawFlux open-source community.\\n\\n\x3c!-- truncate --\x3e\\n\\n## What is JigsawFlux?\\n\\nJigsawFlux is an open-source organisation focused on building tools that make a real difference in health tech, crisis management, and humanitarian response. Every project we build is open, non-profit in spirit, and built to solve real problems that affect real people.\\n\\n## What this blog is for\\n\\nThis blog will be updated weekly or monthly with:\\n\\n- **Project updates** \u2014 what we\'re building, what\'s shipping, what\'s next\\n- **Technical deep-dives** \u2014 architecture decisions, lessons learned, interesting engineering problems\\n- **Community stories** \u2014 contributors, use cases, and the humans behind the code\\n- **Ideas and proposals** \u2014 things we\'re thinking about, inviting input before we build\\n\\n## Get involved\\n\\nIf you want to contribute \u2014 code, documentation, design, testing, or ideas \u2014 the best place to start is [jigsawflux.org/contribute](https://jigsawflux.org/contribute). Every bit helps.\\n\\nYou can also follow along via the [RSS feed](/blog/rss.xml) or the [GitHub organisation](https://github.com/JigsawFlux).\\n\\nHere\'s to building tools that matter."}]}}')}}]);